// 1. Trap instructions in executable sections (self-trap & anti-attach)
let a = arch();
let traps = [];
if a == "aarch64" {
  traps = [["00 00 20 D4", "BRK Instruction", "brk #0 in executable code — compiler trap, sanitizer or self-breakpoint anti-debug"]];
} else if a == "arm" {
  traps = [["70 00 20 E1", "BKPT Instruction", "bkpt in executable code — breakpoint instruction (anti-debug or debug build artifact)"]];
} else {
  traps = [["CC CC CC CC", "INT3 Sequence", "int3 sequence in executable code — debugger breakpoints or trap padding"]];
}
for t in traps {
  let hits = find_bytes(t[0]);
  for h in hits {
    if is_executable(h) {
      report(t[1], h, "MEDIUM", t[2]);
    }
  }
}

// 2. Timing primitives (timing-delta anti-debug: measure elapsed time around sensitive code)
let timing = ["clock_gettime", "gettimeofday"];
for t in timing {
  let syms = find_symbols(t);
  for s in syms {
    if s.name == t || s.name.ends_with("::" + t) {
      report("Timing Source (" + t + ")", s.address, "MEDIUM", "Timing primitive — often used for timing-delta anti-debug around protected code");
    }
  }
}

// 3. Signal handling (SIGTRAP/SIGILL/SIGSEGV handlers used to catch breakpoints and single-steps)
let sig = ["sigaction", "signal"];
for t in sig {
  let syms = find_symbols(t);
  for s in syms {
    if s.name == t || s.name.ends_with("::" + t) {
      report("Signal Install (" + t + ")", s.address, "MEDIUM", "Installs a signal handler — commonly SIGTRAP/SIGILL to catch debuggers and breakpoint patching");
    }
  }
}

// 4. Build/property probes (behavioral divergence on debuggable or unsigned builds)
let props = [
  ["ro.debuggable", "Debuggable Property Probe", "HIGH", "Reads ro.debuggable — changes behavior on debuggable builds"],
  ["ro.secure", "Secure Property Probe", "MEDIUM", "Reads ro.secure — device-security state check"],
  ["ro.build.tags", "Build Tags Probe", "MEDIUM", "Reads ro.build.tags — release-keys vs test-keys check"],
  ["test-keys", "Test Keys Check", "HIGH", "References test-keys — detects unofficial or re-signed builds"]
];
for p in props {
  let hits = find_strings(p[0]);
  for h in hits {
    report(p[1], h.address, p[2], h.value + " (" + p[3] + ")");
  }
}

// 5. Self-readback of own code (compare in-memory code against on-disk to detect inline hooks/patches)
let mems = [
  ["/proc/self/mem", "Self Memory Readback", "HIGH", "Reads its own memory via /proc/self/mem — classic inline-hook and patch detection"],
  ["/proc/%d/mem", "PID Memory Readback", "HIGH", "Reads process memory via /proc/<pid>/mem — hook/tamper verification"],
  ["/proc/self/pagemap", "Pagemap Inspection", "MEDIUM", "Reads /proc/self/pagemap — low-level memory layout inspection"]
];
for m in mems {
  let hits = find_strings(m[0]);
  for h in hits {
    report(m[1], h.address, m[2], h.value);
  }
}

// 6. Checksum primitives (self-integrity CRC of code or data sections)
let cs = ["crc32", "adler32"];
for t in cs {
  let syms = find_symbols(t);
  for s in syms {
    if s.name == t || s.name.ends_with("::" + t) {
      report("Checksum Primitive (" + t + ")", s.address, "MEDIUM", "Hash function linked in — often used to self-verify code sections against tampering");
    }
  }
}
